strategy_code:
# 买：开盘夹档 + 高开回踩夹档（不改写「开盘MA5/MA10夹档买入」）
# - 均线：只读 昨MA5 / 昨MA10；缺字段报错跳过，禁止回退
# - 开盘：只读 今开盘；缺失报错跳过；开盘涨停不买
# - 分支：
#     开盘夹档：min(昨MA5,昨MA10) ≤ 今开 ≤ max(...) → 开盘卖一买入（同原策略）
#     高开回踩：今开 > 夹档上沿 → single_buy@上沿，盘中首次跌回上沿及以下买入
#     低开（今开 < 下沿）：跳过（第一版不做抄底）
# - 仓位：params.sizing_mode
#     fixed（默认）= buy_amount_per_stock
#     clip_equity = 每笔=min(总权益/clip(S,L,U), 当时现金)；生成时不按挂单只数平分现金；两类候选合计最多买 U 只；下单时再按当时现金截断
# - 超 U 截断：先按强度分保留「开盘夹档」合格，剩余名额再按强度分给「高开回踩」（非导出行序/max_per_tag）
# - 建议生成时刻 09:25
#
# params：sizing_mode, buy_amount_per_stock, min_order_amount, clip_L, clip_U

LIMIT_OPEN_EPS = 0.011


def run(codes, prices, get_name, account, params):
    result = []
    params = params or {}
    account = account or {}
    amount_fixed = float(params.get("buy_amount_per_stock", 50000))
    min_order_amount = float(params.get("min_order_amount", 5000))
    sizing_mode = str(params.get("sizing_mode") or "fixed").strip().lower()
    if sizing_mode in ("clip", "account_clip", "clip_s"):
        sizing_mode = "clip_equity"

    def vol_for(amt, price):
        """按金额算整手；买不起 1 手则返回 0（禁止强行 100 股）。"""
        if price <= 0 or amt <= 0:
            return 0
        v = int(amt / price / 100) * 100
        if v < 100:
            return 0
        if v * price < min_order_amount:
            return 0
        return v

    def _require_float(p, key, code_6):
        if not isinstance(p, dict) or key not in p:
            keys = sorted(p.keys()) if isinstance(p, dict) else type(p)
            return None, (
                f"缺少必填行情字段 {key!r}（禁止回退其它字段） keys={keys}"
            )
        raw = p.get(key)
        try:
            v = float(raw)
        except (TypeError, ValueError):
            return None, f"字段 {key!r} 无法转为浮点: {raw!r}"
        if not (v == v) or v <= 0:
            return None, f"字段 {key!r} 无效: {raw!r}"
        return v, None

    def _f(p, *keys):
        for k in keys:
            try:
                v = float(p.get(k) or 0)
            except (TypeError, ValueError):
                v = 0.0
            if v > 0:
                return v
        return 0.0

    def _limits(code_6, p):
        lu = _f(p, "涨停板", "limit_up")
        ld = _f(p, "跌停板", "limit_down")
        if lu > 0 and ld > 0 and lu >= ld:
            return ld, lu
        pre = _f(p, "昨收盘", "pre_close")
        if pre <= 0:
            return 0.0, 0.0
        if code_6.startswith(("300", "301", "688", "689")):
            up_r, down_r = 1.2, 0.8
        else:
            up_r, down_r = 1.1, 0.9
        return round(pre * down_r, 2), round(pre * up_r, 2)

    if not codes:
        print("[开盘夹档+高开回踩] 股票池为空：请先导入选股/填写股票代码")
        return result

    top_n = params.get("generate_top_n")
    try:
        top_n_i = int(top_n) if top_n is not None else 0
    except (TypeError, ValueError):
        top_n_i = 0
    if sizing_mode == "clip_equity" and top_n_i > 0:
        print(
            f"[开盘夹档+高开回踩] 提示: generate_top_n={top_n_i}，S 以截断后池子为准；"
            f"当 N>=U 时通常不影响 clip 单票比例"
        )

    n_skip_field = 0
    n_skip_low = 0
    n_skip_amt = 0
    n_skip_limit = 0
    n_skip_limit_open = 0
    n_skip_cap = 0
    n_skip_trig = 0
    hits = []

    for code in codes:
        code_6 = (code or "").strip()
        if len(code_6) < 6:
            code_6 = code_6.zfill(6)
        p = prices.get(code_6) or prices.get(code) or {}
        if not isinstance(p, dict):
            p = {}

        name = (get_name(code_6) if get_name else "") or ""

        open_px, err = _require_float(p, "今开盘", code_6)
        if err:
            n_skip_field += 1
            print(f"[开盘夹档+高开回踩] {code_6} 报错跳过: {err}")
            continue

        ma5, err = _require_float(p, "昨MA5", code_6)
        if err:
            n_skip_field += 1
            print(f"[开盘夹档+高开回踩] {code_6} 报错跳过: {err}")
            continue

        ma10, err = _require_float(p, "昨MA10", code_6)
        if err:
            n_skip_field += 1
            print(f"[开盘夹档+高开回踩] {code_6} 报错跳过: {err}")
            continue

        lo = min(ma5, ma10)
        hi = max(ma5, ma10)

        ld, lu = _limits(code_6, p)
        if lu <= 0 or ld <= 0:
            n_skip_limit += 1
            print(f"[开盘夹档+高开回踩] {code_6} 跳过: 无涨跌停 (昨收={p.get('昨收盘')!r})")
            continue

        is_limit_open = open_px + 1e-9 >= lu - LIMIT_OPEN_EPS
        if is_limit_open:
            n_skip_limit_open += 1
            print(
                f"[开盘夹档+高开回踩] {code_6} 跳过: 开盘涨停 open={open_px:.2f} lu={lu:.2f}"
            )
            continue

        if open_px + 1e-9 < lo:
            n_skip_low += 1
            print(
                f"[开盘夹档+高开回踩] {code_6} 跳过: 低开不抄底 "
                f"open={open_px:.2f} lo={lo:.2f} hi={hi:.2f}"
            )
            continue

        if lo - 1e-9 <= open_px <= hi + 1e-9:
            branch = "open_band"
            # 与原开盘夹档一致：涨停价触发 + 开盘卖一
            trig = max(ld, min(lu, round(float(lu), 2)))
            size_px = open_px
        else:
            # 高开：盘中回踩夹档上沿
            branch = "gap_pullback"
            trig = max(ld, min(lu, round(float(hi), 2)))
            if trig <= 0 or trig + 1e-9 < ld or trig - 1e-9 > lu:
                n_skip_trig += 1
                print(
                    f"[开盘夹档+高开回踩] {code_6} 跳过: 回踩触发价无效 "
                    f"hi={hi:.2f} trig={trig:.2f} ld={ld:.2f} lu={lu:.2f}"
                )
                continue
            # 高开但触发价已不低于开盘（异常）则无法「跌到触发价」
            if open_px <= trig + 1e-9:
                n_skip_trig += 1
                print(
                    f"[开盘夹档+高开回踩] {code_6} 跳过: 高开分支但 open<=trig "
                    f"open={open_px:.2f} trig={trig:.2f}"
                )
                continue
            size_px = trig

        hits.append({
            "code_6": code_6,
            "name": name,
            "branch": branch,
            "open_px": open_px,
            "lo": lo,
            "hi": hi,
            "ma5": ma5,
            "ma10": ma10,
            "trig": trig,
            "size_px": size_px,
            "lu": lu,
        })


    # clip 强度键：与 sector_stock_filter.EXPORT_ELIG_WEIGHT / 导出 base score 对齐，但不做 max_per_tag
    # 注意：clip 排名 ≠ 导出 xls 行序（导出仍可 max_per_tag 展示）
    CLIP_ELIG_WEIGHT = 8

    def _rank_int(v, default=10 ** 9):
        try:
            if v is None or v == "":
                return default
            return int(float(v))
        except (TypeError, ValueError):
            return default

    def _clip_strength_key(h):
        code_6 = h["code_6"]
        p = prices.get(code_6) or {}
        if not isinstance(p, dict):
            p = {}
        strength = (params.get("clip_strength_by_code") or {}) if isinstance(params, dict) else {}
        meta = strength.get(code_6) if isinstance(strength, dict) else None
        if not isinstance(meta, dict):
            meta = {}
        elig = _rank_int(meta.get("合格榜内序位", p.get("合格榜内序位", h.get("elig"))))
        rs = _rank_int(meta.get("合格榜标签内RS排名", p.get("合格榜标签内RS排名", h.get("rs"))))
        return (elig * CLIP_ELIG_WEIGHT + rs, elig, rs, code_6)

    S = len(codes)
    if sizing_mode == "clip_equity":
        try:
            L = max(1, int(params.get("clip_L", 2)))
        except (TypeError, ValueError):
            L = 2
        try:
            U = max(1, int(params.get("clip_U", 4)))
        except (TypeError, ValueError):
            U = 4
        if U < L:
            U = L
        S_eff = min(U, max(L, int(S)))
        try:
            eq = float(account.get("total_asset") or 0)
        except (TypeError, ValueError):
            eq = 0.0
        try:
            cash = float(account.get("cash") or 0)
        except (TypeError, ValueError):
            cash = 0.0

        n_open = sum(1 for h in hits if h["branch"] == "open_band")
        n_gap = sum(1 for h in hits if h["branch"] == "gap_pullback")
        print(
            f"[开盘夹档+高开回踩] 账户 total_asset={eq:.2f} cash={cash:.2f} "
            f"S={S} L={L} U={U} S_eff={S_eff} 候选={len(hits)} "
            f"(开盘夹档={n_open} 高开回踩={n_gap})"
        )

        if cash <= 1e-6:
            print("[开盘夹档+高开回踩] 可用资金为 0 或无效，不生成买入任务")
            return result

        if len(hits) > S_eff:
            # 开盘夹档优先，同分支内按强度分（≠ 导出行序 / max_per_tag）
            open_hits = sorted(
                [h for h in hits if h["branch"] == "open_band"],
                key=_clip_strength_key,
            )
            gap_hits = sorted(
                [h for h in hits if h["branch"] == "gap_pullback"],
                key=_clip_strength_key,
            )
            kept = open_hits[:S_eff]
            remain = S_eff - len(kept)
            if remain > 0:
                kept.extend(gap_hits[:remain])
            n_skip_cap = len(hits) - len(kept)
            n_keep_open = sum(1 for h in kept if h["branch"] == "open_band")
            n_keep_gap = sum(1 for h in kept if h["branch"] == "gap_pullback")
            print(
                f"[开盘夹档+高开回踩] 候选{len(hits)}只 > U/S_eff={S_eff}，"
                f"开盘优先+强度分：开盘{n_keep_open}+回踩{n_keep_gap}="
                f"{len(kept)}只（截掉{n_skip_cap}；非导出行序）"
            )
            hits = kept

        target = (eq if eq > 0 else cash) / float(S_eff)
        amount_per = min(target, cash) if hits else 0.0
        print(
            f"[开盘夹档+高开回踩] 仓位 clip_equity target={target:.0f} "
            f"amt={amount_per:.0f} (min目标与当时现金，不平分)"
        )
    else:
        amount_per = amount_fixed
        print(f"[开盘夹档+高开回踩] 仓位 fixed amt={amount_per:.0f}")

    for h in hits:
        code_6 = h["code_6"]
        v = vol_for(amount_per, h["size_px"])
        if v <= 0:
            n_skip_amt += 1
            print(
                f"[开盘夹档+高开回踩] {code_6} 跳过: 金额不足买1手 "
                f"(amt={amount_per:.0f} size_px={h['size_px']:.2f})"
            )
            continue

        if h["branch"] == "open_band":
            print(
                f"[开盘夹档+高开回踩] {code_6} 开盘夹档 open={h['open_px']:.2f} "
                f"[{h['lo']:.2f},{h['hi']:.2f}] → 卖一买入 触发价={h['trig']:.2f} "
                f"量={v} 金额约={amount_per:.0f}"
            )
            result.append({
                "stock_code": code_6,
                "stock_name": h["name"],
                "rule_type": "single_buy",
                "name": "开盘买入-夹档",
                "price": h["trig"],
                "volume": v,
                "limit_up": round(float(h["lu"]), 2),
                "wait_unseal": False,
                "open_buy_ask": True,
                "early_order_enabled": False,
            })
        else:
            print(
                f"[开盘夹档+高开回踩] {code_6} 高开回踩 open={h['open_px']:.2f} "
                f"[{h['lo']:.2f},{h['hi']:.2f}] → 回踩上沿 "
                f"触发价={h['trig']:.2f} 量={v} 金额约={amount_per:.0f}"
            )
            result.append({
                "stock_code": code_6,
                "stock_name": h["name"],
                "rule_type": "single_buy",
                "name": "高开回踩-夹档上沿",
                "price": h["trig"],
                "volume": v,
                "limit_up": round(float(h["lu"]), 2),
                "wait_unseal": False,
                "open_buy_ask": False,
                "early_order_enabled": False,
            })

    n_open_out = sum(1 for x in result if x.get("name") == "开盘买入-夹档")
    n_gap_out = sum(1 for x in result if x.get("name") == "高开回踩-夹档上沿")
    print(
        f"[开盘夹档+高开回踩] 合计生成 {len(result)} 条 "
        f"(开盘夹档={n_open_out} 高开回踩={n_gap_out}) | 池={S} "
        f"字段报错跳过={n_skip_field} 低开跳过={n_skip_low} "
        f"无涨跌停={n_skip_limit} 开盘涨停跳过={n_skip_limit_open} "
        f"触发价无效={n_skip_trig} 超U截断={n_skip_cap} 金额不足={n_skip_amt}"
    )
    return result
